// @whimtex-effect Learn/Final Tint
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param color _Tint = #FFFFFF
// @param float _Brightness = 1 [0 .. ~3]


float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Vertical Spiky Gradient
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @group(Placement)
// @param point _Center = (0.5, 0.5)
// @param float2 _Scale = (1, 1)
// @param float _Angle = 0 [-180 .. 180]
// @endgroup
// @group(Structure)
// @param float _Seed = 123 [1 .. ~5000]
// @param float _Peaks = 6 [2 .. 16]
// @param float _Height = 0.95 [0.1 .. 1.5]
// @param float _Width = 0.09 [0.01 .. 0.2]
// @param float _Variation = 0.75 [0 .. 1]
// @param float _BaseHeight = 0.18 [0.02 .. 0.5]
// @endgroup
// @group(Detail)
// @param float _Filaments = 180 [16 .. 400]
// @param float _Texture = 0.5 [0 .. 1]
// @param float _BottomFade = 0.075 [0 .. 0.3]
// @param float _Density = 2.1 [0.1 .. 4]
// @endgroup
// @param gradient _Heat = #FF3F00 -> #FFFFDD
// @param bool _Colored = false
float CurtainHash(float x){return frac(sin(x*127.1+_Seed*311.7)*43758.5453);}
float CurtainNoise(float x,float cells,float salt){
 cells=max(1,round(cells));float p=frac(x)*cells;float i=floor(p),f=frac(p);
 float j=i+1;if(j>=cells)j=0;
 return lerp(CurtainHash(i+salt),CurtainHash(j+salt),f*f*(3-2*f));
}
float4 ApplyFX(float2 uv,float4 color){
 float2 p=LayerToLocal(uv)-_Center;
 float c=cos(radians(_Angle)),s=sin(radians(_Angle));
 float2 q=float2(c*p.x+s*p.y,-s*p.x+c*p.y)/max(abs(_Scale),.001)+.5;
 float y=max(q.y,0),count=round(_Peaks);
 float grain=CurtainNoise(q.x,_Filaments,0);
 float detail=.65*grain+.35*CurtainNoise(q.x,_Filaments*2.37,78);
 float density=exp(-pow(y/max(_BaseHeight,.001),1.5))*1.1;
 [loop] for(int i=0;i<16;i++){
  if(i>=count)break;
  float h=CurtainHash(i+3.7),w=CurtainHash(i+41.2),a=CurtainHash(i+97.6);
  float center=(i+.5+(h-.5)*.7)/count;
  float height=_Height*lerp(1,lerp(.32,1,a),_Variation);
  height*=lerp(1,.82+.34*grain,_Texture);
  float width=_Width*lerp(.6,1.4,w);
  float d=q.x-center;d-=round(d);
  float taper=pow(saturate(1-y/max(height,.001)),1.4);
  float localWidth=max(.0008,width*taper);
  float vertical=pow(saturate(1-y/max(height,.001)),.85);
  float profile=exp(-pow(abs(d)/localWidth,1.25));
  density+=lerp(.85,1.65,h)*vertical*profile;
 }
 [loop] for(int j=0;j<12;j++){
  float center=(j+.5+(CurtainHash(j+155)-.5)*.9)/12;
  float d=q.x-center;d-=round(d);
  float height=lerp(.23,.53,CurtainHash(j+233))*(.85+.3*grain);
  float t=saturate(1-y/height);
  float w=.024*pow(t,1.25)+.0006;
  density+=.45*pow(t,.8)*exp(-abs(d)/w);
 }
 float envelope=pow(saturate(1-y/.52),2);
 density+=envelope*.24*pow(CurtainNoise(q.x,47,15),3);
 density*=lerp(1,lerp(.55,1.35,detail),_Texture);
 float alpha=1-exp(-density*_Density);
 alpha*=smoothstep(0,max(_BottomFade,.00001),q.y)*(1-smoothstep(.94,1,q.y));
 float4 tint=_Heat_Sample(saturate(alpha));
 return float4(lerp(float3(1,1,1),tint.rgb,_Colored),saturate(alpha)*_Opacity*lerp(1,tint.a,_Colored));
}
